type Papel = "admin" | "leitor";

interface Utilizador {
  id: number;
  nome: string;
  papel: Papel;
  email?: string;
}

const PAPEIS: readonly string[] = ["admin", "leitor"];

function ePapel(x: unknown): x is Papel {
  return typeof x === "string" && PAPEIS.includes(x);
}

function eUtilizador(x: unknown): x is Utilizador {
  if (typeof x !== "object" || x === null) return false;
  // Record<string, unknown> permite ler qualquer campo, sempre como unknown
  const o = x as Record<string, unknown>;
  return (
    typeof o.id === "number" &&
    typeof o.nome === "string" &&
    ePapel(o.papel) &&
    // opcional: pode faltar, mas se existir tem de ser string
    (o.email === undefined || typeof o.email === "string")
  );
}

const entradas: unknown[] = [
  JSON.parse('{"id": 1, "nome": "Ana", "papel": "admin"}'),
  JSON.parse('{"id": 2, "nome": "Rui", "papel": "editor"}'),
  JSON.parse('{"id": "3", "nome": "Eva", "papel": "leitor"}'),
  JSON.parse('{"id": 4, "nome": "Luis", "papel": "leitor", "email": 42}'),
  null,
];

for (const e of entradas) {
  if (eUtilizador(e)) {
    // aqui e: Utilizador
    console.log("válido:", e.nome, e.papel);
  } else {
    console.log("rejeitado:", JSON.stringify(e));
  }
}
// válido: Ana admin
// rejeitado: {"id":2,"nome":"Rui","papel":"editor"}
// rejeitado: {"id":"3","nome":"Eva","papel":"leitor"}
// rejeitado: {"id":4,"nome":"Luis","papel":"leitor","email":42}
// rejeitado: null

interface Utilizador {
  id: number;
  nome: string;
  papel: "admin" | "leitor";
}

// Compila sem queixas: o compilador não confere o corpo com a promessa
function eUtilizadorMentiroso(x: unknown): x is Utilizador {
  return typeof x === "object" && x !== null && "id" in x;
}

const dados: unknown = JSON.parse('{"id": 7}');

if (eUtilizadorMentiroso(dados)) {
  // dados: Utilizador, segundo o compilador
  try {
    console.log(dados.nome.toUpperCase());
  } catch (e) {
    console.log("rebentou em runtime:", (e as Error).message);
  }
}
// rebentou em runtime: Cannot read properties of undefined (reading 'toUpperCase')

// Nem sequer é preciso verificar nada: isto também compila
function eSempreUtilizador(x: unknown): x is Utilizador {
  return true;
}
console.log(eSempreUtilizador(42)); // true

interface Config {
  porta: number;
  anfitriao: string;
}

function eConfig(x: unknown): x is Config {
  if (typeof x !== "object" || x === null) return false;
  const o = x as Record<string, unknown>;
  return typeof o.porta === "number" && typeof o.anfitriao === "string";
}

// Declaração de função: serve como asserção sem mais nada
function assertConfig(x: unknown): asserts x is Config {
  if (!eConfig(x)) {
    throw new Error("configuração inválida: " + JSON.stringify(x));
  }
}

// Arrow function: só funciona com a anotação de tipo na própria constante
const assertConfigArrow: (x: unknown) => asserts x is Config = (x) => {
  if (!eConfig(x)) throw new Error("configuração inválida");
};

// Sem anotação na constante, a chamada é rejeitada
const assertSemAnotacao = (x: unknown): asserts x is Config => {
  if (!eConfig(x)) throw new Error("configuração inválida");
};

const bruto: unknown = JSON.parse('{"porta": 8080, "anfitriao": "localhost"}');
assertConfig(bruto);
console.log(bruto.porta); // 8080 (bruto: Config daqui para baixo)

const outro: unknown = JSON.parse('{"porta": 3000, "anfitriao": "0.0.0.0"}');
assertConfigArrow(outro);
console.log(outro.anfitriao); // 0.0.0.0 (outro: Config)

const terceiro: unknown = JSON.parse('{"porta": 1}');
try {
  // @ts-expect-error TS2775: Assertions require every name in the call target to be declared with an explicit type annotation.
  assertSemAnotacao(terceiro);
} catch (e) {
  console.log((e as Error).message); // configuração inválida
}

interface Morada {
  rua: string;
  codigoPostal: string;
}

interface Cliente {
  nome: string;
  morada: Morada;
  etiquetas: string[];
}

function eRegisto(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}

function eString(x: unknown): x is string {
  return typeof x === "string";
}

function eMorada(x: unknown): x is Morada {
  return eRegisto(x) && eString(x.rua) && eString(x.codigoPostal);
}

function eCliente(x: unknown): x is Cliente {
  return (
    eRegisto(x) &&
    eString(x.nome) &&
    eMorada(x.morada) && // objeto dentro de objeto: reutiliza o predicado
    Array.isArray(x.etiquetas) &&
    x.etiquetas.every(eString) // cada elemento é validado
  );
}

// every com um predicado estreita o próprio array
const lista: unknown[] = JSON.parse('["norte", "vip"]');
if (lista.every(eString)) {
  const maiusculas: string[] = lista.map((s) => s.toUpperCase()); // lista: string[]
  console.log(maiusculas); // [ 'NORTE', 'VIP' ]
}

const texto = '{"nome": "Marta", "morada": {"rua": "Rua Direita", "codigoPostal": 4000}, "etiquetas": ["vip"]}';
console.log(eCliente(JSON.parse(texto))); // false (codigoPostal é number)

const corrigido = '{"nome": "Marta", "morada": {"rua": "Rua Direita", "codigoPostal": "4000-123"}, "etiquetas": ["vip"]}';
const c: unknown = JSON.parse(corrigido);
if (eCliente(c)) {
  console.log(c.morada.codigoPostal, c.etiquetas.length); // 4000-123 1
}

type Validador<T> = (x: unknown) => x is T;
type TipoDe<V> = V extends Validador<infer T> ? T : never;

const eString: Validador<string> = (x): x is string => typeof x === "string";
const eNumero: Validador<number> = (x): x is number => typeof x === "number";

function eLiteral<const L extends readonly (string | number)[]>(...valores: L): Validador<L[number]> {
  return (x): x is L[number] => valores.includes(x as L[number]);
}

function eArrayDe<T>(v: Validador<T>): Validador<T[]> {
  return (x): x is T[] => Array.isArray(x) && x.every(v);
}

function eObjeto<E extends Record<string, Validador<unknown>>>(
  esquema: E
): Validador<{ [K in keyof E]: TipoDe<E[K]> }> {
  return (x): x is { [K in keyof E]: TipoDe<E[K]> } => {
    if (typeof x !== "object" || x === null) return false;
    const o = x as Record<string, unknown>;
    return Object.keys(esquema).every((chave) => esquema[chave](o[chave]));
  };
}

// Um único esquema em runtime...
const eUtilizador = eObjeto({
  id: eNumero,
  nome: eString,
  papel: eLiteral("admin", "leitor"),
  morada: eObjeto({ rua: eString, codigoPostal: eString }),
  etiquetas: eArrayDe(eString),
});

// ...e o tipo estático derivado dele, sem o escrever duas vezes
type Utilizador = TipoDe<typeof eUtilizador>;
// { id: number; nome: string; papel: "admin" | "leitor";
//   morada: { rua: string; codigoPostal: string }; etiquetas: string[] }

const dados: unknown = JSON.parse(
  '{"id": 1, "nome": "Ana", "papel": "admin", "morada": {"rua": "Rua Nova", "codigoPostal": "1000-001"}, "etiquetas": []}'
);

if (eUtilizador(dados)) {
  const u: Utilizador = dados;
  console.log(u.papel, u.morada.codigoPostal); // admin 1000-001
}
console.log(eUtilizador({ id: 1, nome: "Rui", papel: "editor" })); // false

// Cada verificador devolve a lista de problemas (lista vazia = válido)
type Verificador = (x: unknown, caminho: string) => string[];

function tipoDe(x: unknown): string {
  if (x === null) return "null";
  if (Array.isArray(x)) return "array";
  return typeof x;
}

const texto: Verificador = (x, caminho) =>
  typeof x === "string" ? [] : [`${caminho}: esperava string, recebeu ${tipoDe(x)}`];

const numero: Verificador = (x, caminho) =>
  typeof x === "number" ? [] : [`${caminho}: esperava number, recebeu ${tipoDe(x)}`];

function objeto(esquema: Record<string, Verificador>): Verificador {
  return (x, caminho) => {
    if (typeof x !== "object" || x === null || Array.isArray(x)) {
      return [`${caminho || "(raiz)"}: esperava objeto, recebeu ${tipoDe(x)}`];
    }
    const o = x as Record<string, unknown>;
    // não pára no primeiro: junta os problemas de todos os campos
    return Object.entries(esquema).flatMap(([chave, verificar]) =>
      verificar(o[chave], caminho ? `${caminho}.${chave}` : chave)
    );
  };
}

function arrayDe(verificar: Verificador): Verificador {
  return (x, caminho) =>
    Array.isArray(x)
      ? x.flatMap((elem, i) => verificar(elem, `${caminho}[${i}]`))
      : [`${caminho}: esperava array, recebeu ${tipoDe(x)}`];
}

const verificarCliente = objeto({
  nome: texto,
  idade: numero,
  morada: objeto({ rua: texto, codigoPostal: texto }),
  telefones: arrayDe(texto),
});

const entrada: unknown = JSON.parse(
  '{"nome": "Marta", "idade": "40", "morada": {"rua": "Rua Direita", "codigoPostal": 4000}, "telefones": ["912", 913]}'
);

console.log(verificarCliente(entrada, ""));
// [
//   'idade: esperava number, recebeu string',
//   'morada.codigoPostal: esperava string, recebeu number',
//   'telefones[1]: esperava string, recebeu number'
// ]
console.log(verificarCliente(null, "")); // [ '(raiz): esperava objeto, recebeu null' ]

interface Encomenda {
  id: string;
  total: number;
}

function eEncomenda(x: unknown): x is Encomenda {
  if (typeof x !== "object" || x === null) return false;
  const o = x as Record<string, unknown>;
  return typeof o.id === "string" && typeof o.total === "number";
}

// Fronteira: o único sítio onde entra unknown e onde se valida
function lerEncomendas(json: string): Encomenda[] {
  const bruto: unknown = JSON.parse(json);
  if (!Array.isArray(bruto) || !bruto.every(eEncomenda)) {
    throw new Error("resposta com formato inesperado");
  }
  return bruto;
}

// Interior: recebe Encomenda[] e confia no tipo, sem voltar a validar
function somarTotais(encomendas: Encomenda[]): number {
  return encomendas.reduce((soma, e) => soma + e.total, 0);
}

const resposta = '[{"id": "A1", "total": 12.5}, {"id": "A2", "total": 7.5}]';
console.log(somarTotais(lerEncomendas(resposta))); // 20

// O custo de não validar: um as silencia o compilador e o erro passa
const semValidar = JSON.parse('[{"id": "A3", "total": "10"}]') as Encomenda[];
console.log(somarTotais(semValidar)); // 010 (concatenou strings, não somou)

try {
  lerEncomendas('[{"id": "A3", "total": "10"}]');
} catch (e) {
  console.log((e as Error).message); // resposta com formato inesperado
}

