interface Produto {
  nome: string;
  preco: number;
  emStock: boolean;
  categoria?: string;
}

function eProduto(x: unknown): x is Produto {
  if (typeof x !== "object" || x === null) return false;
  const o = x as Record<string, unknown>;
  return (
    typeof o.nome === "string" &&
    typeof o.preco === "number" &&
    typeof o.emStock === "boolean" &&
    (o.categoria === undefined || typeof o.categoria === "string")
  );
}

const testes = [
  '{"nome": "Caneta", "preco": 1.2, "emStock": true}',
  '{"nome": "Lápis", "preco": 0.5, "emStock": false, "categoria": "escrita"}',
