  '{"nome": "Régua", "preco": 2, "emStock": true, "categoria": 5}',
];

for (const t of testes) {
  const dados: unknown = JSON.parse(t);
  console.log(eProduto(dados) ? `ok: ${dados.nome}` : "rejeitado");
}
// ok: Caneta
// ok: Lápis
// rejeitado
// rejeitado

interface Linha {
  produto: string;
  quantidade: number;
}

interface Pedido {
  cliente: string;
  linhas: Linha[];
}

function eLinha(x: unknown): x is Linha {
  if (typeof x !== "object" || x === null) return false;
  const o = x as Record<string, unknown>;
  return typeof o.produto === "string" && typeof o.quantidade === "number" && o.quantidade > 0;
}

// A anotação na constante é obrigatória para a chamada estreitar (senão TS2775)
const assertPedido: (x: unknown) => asserts x is Pedido = (x) => {
  if (typeof x !== "object" || x === null) throw new Error("pedido: esperava objeto");
  const o = x as Record<string, unknown>;
  if (typeof o.cliente !== "string") throw new Error("pedido.cliente: esperava string");
  if (!Array.isArray(o.linhas) || !o.linhas.every(eLinha)) {
    throw new Error("pedido.linhas: formato inválido");
  }
};

function processar(json: string): void {
  const dados: unknown = JSON.parse(json);
  try {
    assertPedido(dados);
    const unidades = dados.linhas.reduce((s, l) => s + l.quantidade, 0);
    console.log(`${dados.cliente}: ${unidades} unidades`);
  } catch (e) {
    console.log("erro:", (e as Error).message);
  }
}

processar('{"cliente": "Ana", "linhas": [{"produto": "Caneta", "quantidade": 3}, {"produto": "Lápis", "quantidade": 2}]}');
processar('{"cliente": "Rui", "linhas": [{"produto": "Caneta", "quantidade": 0}]}');
processar('{"linhas": []}');
// Ana: 5 unidades
// erro: pedido.linhas: formato inválido
// erro: pedido.cliente: esperava string

type Validador<T> = (x: unknown) => x is T;
type TipoDe<V> = V extends Validador<infer T> ? T : never;

const eString: Validador<string> = (x): x is string => typeof x === "string";
const eNumero: Validador<number> = (x): x is number => typeof x === "number";
const eBooleano: Validador<boolean> = (x): x is boolean => typeof x === "boolean";

function eOpcional<T>(v: Validador<T>): Validador<T | undefined> {
  return (x): x is T | undefined => x === undefined || v(x);
}

function eArrayDe<T>(v: Validador<T>): Validador<T[]> {
  return (x): x is T[] => Array.isArray(x) && x.every(v);
}

function eObjeto<E extends Record<string, Validador<unknown>>>(
  esquema: E
): Validador<{ [K in keyof E]: TipoDe<E[K]> }> {
  return (x): x is { [K in keyof E]: TipoDe<E[K]> } => {
    if (typeof x !== "object" || x === null) return false;
    const o = x as Record<string, unknown>;
    return Object.keys(esquema).every((chave) => esquema[chave](o[chave]));
  };
}

const eArtigo = eObjeto({
  titulo: eString,
  publicado: eBooleano,
  visitas: eNumero,
  subtitulo: eOpcional(eString),
  autores: eArrayDe(eObjeto({ nome: eString, email: eOpcional(eString) })),
});

type Artigo = TipoDe<typeof eArtigo>;
// { titulo: string; publicado: boolean; visitas: number; subtitulo: string | undefined;
//   autores: { nome: string; email: string | undefined }[] }

const bruto: unknown = JSON.parse(
  '{"titulo": "Tipos na fronteira", "publicado": true, "visitas": 120, "autores": [{"nome": "Ana"}]}'
);

if (eArtigo(bruto)) {
  const a: Artigo = bruto;
  console.log(a.titulo, a.subtitulo ?? "(sem subtítulo)", a.autores[0].nome);
}
// Tipos na fronteira (sem subtítulo) Ana
console.log(eArtigo({ titulo: "X", publicado: "sim", visitas: 1, autores: [] })); // false

type Verificador = (x: unknown, caminho: string) => string[];

function tipoDe(x: unknown): string {
  if (x === null) return "null";
  if (Array.isArray(x)) return "array";
  return typeof x;
}

const texto: Verificador = (x, c) =>
  typeof x === "string" ? [] : [`${c}: esperava string, recebeu ${tipoDe(x)}`];

const numero: Verificador = (x, c) =>
  typeof x === "number" ? [] : [`${c}: esperava number, recebeu ${tipoDe(x)}`];

function umDe(...valores: readonly string[]): Verificador {
  return (x, c) =>
    typeof x === "string" && valores.includes(x)
      ? []
      : [`${c}: esperava um de ${valores.join(", ")}, recebeu ${JSON.stringify(x)}`];
}

function objeto(esquema: Record<string, Verificador>): Verificador {
  return (x, c) => {
    if (typeof x !== "object" || x === null || Array.isArray(x)) {
      return [`${c || "(raiz)"}: esperava objeto, recebeu ${tipoDe(x)}`];
    }
    const o = x as Record<string, unknown>;
    return Object.entries(esquema).flatMap(([k, v]) => v(o[k], c ? `${c}.${k}` : k));
  };
}

function arrayDe(v: Verificador): Verificador {
  return (x, c) =>
    Array.isArray(x)
      ? x.flatMap((e, i) => v(e, `${c}[${i}]`))
      : [`${c}: esperava array, recebeu ${tipoDe(x)}`];
}

const verificarEncomendas = arrayDe(
  objeto({
    id: texto,
    estado: umDe("pendente", "pago", "enviado"),
    itens: arrayDe(objeto({ produto: texto, preco: numero })),
  })
);

const json = `[
  {"id": "E1", "estado": "pago", "itens": [{"produto": "Caneta", "preco": 1.2}]},
  {"id": 2, "estado": "perdido", "itens": [{"produto": "Lápis", "preco": "0.5"}, {"preco": 3}]},
  {"id": "E3", "estado": "enviado"}
]`;

const problemas = verificarEncomendas(JSON.parse(json), "encomendas");
console.log(problemas.length === 0 ? "tudo válido" : problemas.join("\n"));
// encomendas[1].id: esperava string, recebeu number
// encomendas[1].estado: esperava um de pendente, pago, enviado, recebeu "perdido"
// encomendas[1].itens[0].preco: esperava number, recebeu string
// encomendas[1].itens[1].produto: esperava string, recebeu undefined
// encomendas[2].itens: esperava array, recebeu undefined
